                                                            ((uint64_t)NA_UINT8 << 48) |                        // tsrc2
                                                            ((uint64_t)dst_reg << 40) |                         // rdst1
                                                            ((uint64_t)NA_UINT8 << 32) |                        // rdst2
                                                            ((uint64_t)NA_UINT8 << 24) |                        // rsrc1
