                                                            ((uint64_t)min_reg << 24) |                         // rsrc1
                                                            ((uint64_t)max_reg << 16) |                         // rsrc2
                                                            ((uint64_t)stride_reg << 8) |                       // rsrc3
                                                            (uint64_t)(cond_tile == -1 ? NA_UINT8 : cond_tile); // cond
    *INSTR_baseaddr = (uint64_t)data;                                                                           // baseaddr
    __asm__ __volatile__("mfence;");
}
